<div class="page-heading"><div><div class="eyebrow">YOUR ACCOUNT</div><h1>Security Settings</h1><p>Review active sessions and control which devices can remember you.</p></div></div><div class="row g-4 mb-4"><div class="col-md-6"><section class="surface form-panel"><h2>Google account</h2><p class="mb-1"><?= e($user['email']) ?></p><p class="text-secondary small mb-0">Google is the only sign-in method. Workspace access requires administrator approval.</p></section></div><div class="col-md-6"><section class="surface form-panel"><h2>Session policy</h2><p class="text-secondary small mb-0">Sessions expire after 2 hours of inactivity or 12 hours total. Remembered devices use rotating tokens and expire after 30 days.</p></section></div></div><h2 class="mb-3">Active sessions</h2><div class="surface table-responsive mb-4"><table class="table"><thead><tr><th>Device</th><th>Last active (UTC)</th><th>Expires (UTC)</th><th>Access</th></tr></thead><tbody><?php foreach($sessions as $s): ?><tr><td class="device-name"><?= e($s['device']) ?><?php if ($s['id']===($_SESSION['auth'] ?? '')): ?><span class="status-badge ms-2">This session</span><?php endif; ?></td><td><?= e($s['last_seen']) ?></td><td><?= e($s['expires_at']) ?></td><td><form method="post"><?= csrf() ?><input type="hidden" name="kind" value="session"><input type="hidden" name="id" value="<?= e($s['id']) ?>"><button class="btn btn-sm btn-outline-danger" type="submit">Revoke</button></form></td></tr><?php endforeach; ?></tbody></table></div><h2 class="mb-3">Remembered devices</h2><div class="surface table-responsive mb-4"><table class="table"><thead><tr><th>Device</th><th>Remembered until (UTC)</th><th>Access</th></tr></thead><tbody><?php foreach($devices as $d): ?><tr><td class="device-name"><?= e($d['device']) ?></td><td><?= e($d['expires_at']) ?></td><td><form method="post"><?= csrf() ?><input type="hidden" name="kind" value="device"><input type="hidden" name="id" value="<?= e($d['selector']) ?>"><button class="btn btn-sm btn-outline-danger" type="submit">Forget device</button></form></td></tr><?php endforeach; ?><?php if(!$devices): ?><tr><td colspan="3" class="p-4 text-secondary">No remembered devices.</td></tr><?php endif; ?></tbody></table></div><section class="surface form-panel"><h2>Sign out everywhere</h2><p class="text-secondary">Revoke every active session and remembered device, including this one.</p><form method="post"><?= csrf() ?><input type="hidden" name="kind" value="all"><button class="btn btn-outline-danger" type="submit">Revoke all access</button></form></section>
